def solve(path) -> str:
    """Simplify an absolute Unix‑style path.

    This resolves ``.``, ``..`` and removes redundant slashes. It also works when
    the input is a *bytes* object by decoding it as UTF‑8. Non‑string inputs are
    converted to ``str``. If the resulting path is not absolute, the function
    returns ``/`` as a safe default.
    """
    # Normalise the input to a string.
    if isinstance(path, (bytes, bytearray)):
        try:
            path = path.decode()
        except Exception:
            path = str(path)
    else:
        path = str(path)
    # Guard against empty or non‑absolute paths.
    if not path or not path.startswith('/'):
        return '/'
    parts = path.split('/')
    stack: list = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            continue
        stack.append(part)
    return '/' + '/'.join(stack) if stack else '/'

