def solve(a, x):
    """Return the leftmost index to insert x into sorted list a.
    Uses binary search O(log n). Handles empty list.
    """
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

def solve(weights, values, capacity):
    """0/1 knapsack: maximize total value not exceeding capacity.
    weights and values are lists of same length.
    """
    n = len(weights)
    # Use dp dict for sparse representation
    dp = {0: 0}
    for i in range(n):
        w = weights[i]
        v = values[i]
        # iterate over snapshot of current keys to avoid using newly added entries in same iteration
        for cur_w, cur_v in list(dp.items()):
            new_w = cur_w + w
            if new_w > capacity:
                continue
            new_v = cur_v + v
            if new_w not in dp or new_v > dp[new_w]:
                dp[new_w] = new_v
    # best value is max of dp values
    return max(dp.values()) if dp else 0

