def solve(lst):
    """Flatten a nested list of integers.
    The input is a list which may contain integers or other lists to arbitrary depth.
    Returns a flat list of all integers in the original left-to-right order.
    """
    import sys
    sys.setrecursionlimit(1000000)
    result = []
