def solve(grid):
    """Count the number of islands (connected components of 1s) in a grid.
    grid: list of list of ints (0 or 1). Cells are adjacent vertically or horizontally.
    Returns 0 for empty grid or rows with no columns.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    if cols == 0:
        return 0
    visited = [[False] * cols for _ in range(rows)]
    count = 0
    from collections import deque
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                count += 1
                # BFS to mark all connected land
                dq = deque()
                dq.append((i, j))
                visited[i][j] = True
                while dq:
                    x, y = dq.popleft()
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < rows and 0 <= ny < cols:
                            if grid[nx][ny] == 1 and not visited[nx][ny]:
                                visited[nx][ny] = True
                                dq.append((nx, ny))
    return count

