def solve(a, x):
    """Return the smallest index to insert x into sorted list a.
    Implements binary search manually to avoid reliance on bisect.
    """
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

