def solve(matrix):
    def det(m):
        n = len(m)
        if n == 0:
            return 1
        if n == 1:
            return m[0][0]
        if n == 2:
            return m[0][0]*m[1][1] - m[0][1]*m[1][0]
        total = 0
        for j in range(n):
            minor = [row[:j] + row[j+1:] for row in m[1:]]
            sign = -1 if j % 2 else 1
            total += sign * m[0][j] * det(minor)
