def solve(s):
    """Return length of longest substring without repeating characters.
    Uses sliding window with dictionary storing last index of each character.
    """
    last = {}
    start = 0
    max_len = 0
    for i, ch in enumerate(s):
        if ch in last and last[ch] >= start:
            start = last[ch] + 1
        last[ch] = i
        cur_len = i - start + 1
        if cur_len > max_len:
